changeSet.sql:
UPDATE actions_config ac
SET config = config
  || jsonb_build_object('guidance_url', a.guidance_url)
  || jsonb_build_object('availability', a.availability)
FROM actions a
WHERE ac.code = a.code
  AND (a.guidance_url IS NOT NULL OR a.availability IS NOT NULL);

ALTER TABLE actions DROP COLUMN guidance_url;
ALTER TABLE actions DROP COLUMN availability;
